import{_ as l,a0 as p,w as o,s as r,I as e,x as a,a1 as t,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"在 CentOS 和 RHEL 系統上安裝安全補丁或自動更新 | LCTT x X-CMD","titleTemplate":false,"description":"在 CentOS 和 RHEL 系統上安裝安全補丁或自動更新 | LCTT (201612) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 CentOS 和 RHEL 系統上安裝安全補丁或自動更新 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 CentOS 和 RHEL 系統上安裝安全補丁或自動更新 | LCTT (201612) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201612/20161130 Install Security Patches or Updates Automatically on CentOS and RHEL","title":"在 CentOS 和 RHEL 系統上安裝安全補丁或自動更新","tag":"201612","desc":""},"relativePath":"201612/20161130 Install Security Patches or Updates Automatically on CentOS and RHEL.md","filePath":"[post].md"}'),h={name:"201612/20161130 Install Security Patches or Updates Automatically on CentOS and RHEL.md"};function c(u,s,g,k,m,b){const n=p("Link");return o(),r("div",null,[s[16]||(s[16]=e("h1",{id:"在-centos-和-rhel-系統上安裝安全補丁或自動更新",tabindex:"-1"},[a("在 CentOS 和 RHEL 系統上安裝安全補丁或自動更新 "),e("a",{class:"header-anchor",href:"#在-centos-和-rhel-系統上安裝安全補丁或自動更新","aria-label":"Permalink to “在 CentOS 和 RHEL 系統上安裝安全補丁或自動更新”"},"​")],-1)),s[17]||(s[17]=e("p",null,"在 Linux 系統上，一個最重要的需求就是為相應的 Linux 版本定期安裝最新的安全補丁，或者更新。",-1)),e("p",null,[s[1]||(s[1]=a("在之前的文章中，我們分享了",-1)),t(n,{href:"http://www.tecmint.com/auto-install-security-updates-on-debian-and-ubuntu/"},{default:i(()=>[...s[0]||(s[0]=[a("如何在 Debian/Ubuntu 上配置自動安全更新",-1)])]),_:1}),s[2]||(s[2]=a("，在這篇文章中，我們將分享如何在 CentOS/RHEL 7/6 版本中設置在需要時自動更新重要的安全補丁。",-1))]),s[18]||(s[18]=d(`<p>和它同一家族的其它 Linux 版本（Fedora 或 Scientific Linux）中可以用類似的方法進行配置。</p><h3 id="在-centos-rhel-系統上配置自動安全更新" tabindex="-1">在 CentOS/RHEL 系統上配置自動安全更新 <a class="header-anchor" href="#在-centos-rhel-系統上配置自動安全更新" aria-label="Permalink to “在 CentOS/RHEL 系統上配置自動安全更新”">​</a></h3><p>在 CentOS/RHEL 7/6 系統上，你需要安裝下面的安裝包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum update -y &amp;&amp; yum install yum-cron -y</span></span></code></pre></div><h3 id="在-centos-rhel-7-系統上啓用自動安全更新" tabindex="-1">在 CentOS/RHEL 7　系統上啓用自動安全更新 <a class="header-anchor" href="#在-centos-rhel-7-系統上啓用自動安全更新" aria-label="Permalink to “在 CentOS/RHEL 7　系統上啓用自動安全更新”">​</a></h3><p>安裝完成以後，打開 <code>/etc/yum/yum-cron.conf</code>，然後找到下面這些行內容，你必須確保它們的值和下面展示的一樣</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>update_cmd = security</span></span>
<span class="line"><span>update_messages = yes</span></span>
<span class="line"><span>download_updates = yes</span></span>
<span class="line"><span>apply_updates = yes</span></span></code></pre></div><p>第一行表明自動更新命令列應該像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum --security upgrade</span></span></code></pre></div><p>而其它的行保證了能夠通知並自動下載、安裝安全升級。</p><p>為了使來自 root@localhost 的通知能夠通過郵件發送給同一賬户（再次説明，你可以選擇其他賬户，如果你想這樣的話），下面這些行也是必須的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>emit_via = email</span></span>
<span class="line"><span>email_from = root@localhost</span></span>
<span class="line"><span>email_to = root</span></span></code></pre></div><h3 id="在-centos-rhel-6-上啓用自動安全更新" tabindex="-1">在 CentOS/RHEL 6 上啓用自動安全更新 <a class="header-anchor" href="#在-centos-rhel-6-上啓用自動安全更新" aria-label="Permalink to “在 CentOS/RHEL 6 上啓用自動安全更新”">​</a></h3><p>默認情況下， cron 任務被配置成了立即下載並安裝所有更新，但是我們可以通過在 <code>/etc/sysconfig/yum-cron</code> 配置文件中把下面兩個參數改為 <code>yes</code>，從而改變這種行為。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 不要安裝，只做檢查（有效值： yes|no）</span></span>
<span class="line"><span>CHECK_ONLY=yes</span></span>
<span class="line"><span># 不要安裝，只做檢查和下載（有效值： yes|no）</span></span>
<span class="line"><span># 要求 CHECK_ONLY=yes（先要檢查後才可以知道要下載什麼）</span></span>
<span class="line"><span>DOWNLOAD_ONLY=yes</span></span></code></pre></div><p>為了啓用關於安裝包更新的郵件通知，你需要把 <code>MAILTO</code> 參數設置為一個有效的郵件地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 默認情況下 MAILTO 是沒有設置的，crond 會將輸出發送郵件給自己（LCTT 譯註：執行 cron 的用户，這裏是 root）</span></span>
<span class="line"><span># 例子： MAILTO=root</span></span>
<span class="line"><span>MAILTO=admin@tecmint.com</span></span></code></pre></div><p>最後，打開並啓用 <code>yum-cron</code> 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>------------- On CentOS/RHEL 7 ------------- </span></span>
<span class="line"><span>systemctl start yum-cron</span></span>
<span class="line"><span>systemctl enable yum-cron</span></span>
<span class="line"><span>------------- On CentOS/RHEL 6 -------------  </span></span>
<span class="line"><span># service yum-cron start</span></span>
<span class="line"><span># chkconfig --level 35 yum-cron on</span></span></code></pre></div><p>恭喜你，你已經成功的在 CentOS/RHEL 7/6 系統上設置了自動升級。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在這篇文章中，我們討論瞭如何保持你的服務器定期更新或升級最新的安全補丁。另外，為了保證當新的補丁被應用時你自己能夠知道，你也學習瞭如何配置郵件通知。</p><p>如果你有任何關於這篇文章的疑問，請在下面的評論區留下你的問題。我們期待收到你的回覆。</p><hr>`,24)),e("p",null,[s[4]||(s[4]=a("via: ",-1)),t(n,{href:"http://www.tecmint.com/auto-install-security-patches-updates-on-centos-rhel/"},{default:i(()=>[...s[3]||(s[3]=[a("http://www.tecmint.com/auto-install-security-patches-updates-on-centos-rhel/",-1)])]),_:1})]),e("p",null,[s[8]||(s[8]=a("作者：",-1)),t(n,{href:"http://www.tecmint.com/author/gacanepa/"},{default:i(()=>[...s[5]||(s[5]=[a("Gabriel Cánepa",-1)])]),_:1}),s[9]||(s[9]=a(" 譯者：",-1)),t(n,{href:"https://github.com/ucasFL"},{default:i(()=>[...s[6]||(s[6]=[a("ucasFL",-1)])]),_:1}),s[10]||(s[10]=a(" 校對：",-1)),t(n,{href:"https://github.com/jasminepeng"},{default:i(()=>[...s[7]||(s[7]=[a("jasminepeng",-1)])]),_:1})]),e("p",null,[s[13]||(s[13]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:i(()=>[...s[12]||(s[12]=[a("Linux中國",-1)])]),_:1}),s[15]||(s[15]=a(" 榮譽推出",-1))])])}const L=l(h,[["render",c]]);export{f as __pageData,L as default};
